class Solution {
    public int longestPalindrome(String word1,String word2){
        String text=word1+word2;
        int n=text.length();
        int[][] dp=new int[n][n];
        for(int i=n-1;i>=0;i--){
            dp[i][i]=1;
            for(int j=i+1;j<n;j++)dp[i][j]=text.charAt(i)==text.charAt(j)?2+(i+1<=j-1?dp[i+1][j-1]:0):Math.max(dp[i+1][j],dp[i][j-1]);
        }
        int answer=0;
        for(int i=0;i<word1.length();i++)for(int j=word1.length();j<n;j++)if(text.charAt(i)==text.charAt(j))answer=Math.max(answer,2+(i+1<=j-1?dp[i+1][j-1]:0));
        return answer;
    }
}

